package main

import (
    "net/http"
    "github.com/gin-gonic/gin"
)

func main() {
    r := gin.Default()
    r.Run(":8080")
}

args.ReplacementContent:
r.GET("/healthz", func(c *gin.Context) {
    commit := os.Getenv("GIT_COMMIT")
    if commit == "" { commit = "dev" }
    c.JSON(http.StatusOK, gin.H{"status": "ok", "commit": commit})
})
r.Run(":8080")
